-- ============================================================================
-- SQL-протокол секции «Посуточная сверка DWH <-> MSSQL AccumRg (п. 6 ТЗ)»
-- Дата аудита: 2026-07-21. Режим: ТОЛЬКО SELECT.
-- PG: 10.10.1.142:5432/test (readonly-сессия). MSSQL: 10.10.1.61:1433/UPP_JAN.
-- Семантика: даты 1С в MSSQL = реальный год + 2000 (4026 == 2026).
-- Фильтр движка (build_accumrg_with_documents, etl_meta.register_sources id=256):
--   WHERE [sales]._Period BETWEEN <start> AND <end>  -- И ВСЁ: where_clause=NULL,
--   фильтра по _Active НЕТ, фильтра по _RecorderTRef НЕТ (типы ограничены только
--   LEFT JOIN'ами обогащения). Поэтому на стороне MSSQL сверяем БЕЗ фильтра _Active,
--   а долю _Active=0x00 меряем отдельно как объясняющий фактор.
-- Поля: _Fld17855=stoimost, _Fld17857=nds, таблица dbo._AccumRg17844.
-- ============================================================================

-- [MSSQL] 2.1 MSSQL посуточно: docs (distinct _RecorderRRef), rows, SUM stoimost, SUM nds — фильтр как у движка (только _Period)
SELECT CAST(DATEADD(year,-2000,_Period) AS date) AS d,
       COUNT(DISTINCT _RecorderRRef) AS docs,
       COUNT(*) AS rws,
       SUM(_Fld17855) AS stoimost,
       SUM(_Fld17857) AS nds
FROM [UPP_JAN].[dbo].[_AccumRg17844]
WHERE _Period >= '4026-06-15' AND _Period < '4026-07-22'
GROUP BY CAST(DATEADD(year,-2000,_Period) AS date)
ORDER BY d

-- [MSSQL] 2.2 MSSQL посуточно по типам регистратора (_RecorderTRef -> int): rows, docs, суммы
SELECT CAST(DATEADD(year,-2000,_Period) AS date) AS d,
       CAST(_RecorderTRef AS int) AS rtype,
       COUNT(DISTINCT _RecorderRRef) AS docs,
       COUNT(*) AS rws,
       SUM(_Fld17855) AS stoimost,
       SUM(_Fld17857) AS nds
FROM [UPP_JAN].[dbo].[_AccumRg17844]
WHERE _Period >= '4026-06-15' AND _Period < '4026-07-22'
GROUP BY CAST(DATEADD(year,-2000,_Period) AS date), CAST(_RecorderTRef AS int)
ORDER BY d, rtype

-- [MSSQL] 2.3 Доля _Active=0x00 (движения снятых с проведения) за период — всего
SELECT _Active, COUNT(*) AS rws, COUNT(DISTINCT _RecorderRRef) AS docs,
       SUM(_Fld17855) AS stoimost, SUM(_Fld17857) AS nds
FROM [UPP_JAN].[dbo].[_AccumRg17844]
WHERE _Period >= '4026-06-15' AND _Period < '4026-07-22'
GROUP BY _Active

-- [PG] 3.0 Контроль времени: now UTC / Almaty, max(period), row counts
SELECT now() AT TIME ZONE 'UTC' AS now_utc, now() AT TIME ZONE 'Asia/Almaty' AS now_almaty,
       (SELECT max(period) FROM sales) AS max_period,
       (SELECT count(*) FROM sales) AS sales_rows,
       (SELECT count(*) FROM sales_positions) AS pos_rows

-- [PG] 3.1 DWH посуточно из sales: distinct recorder (docs)
SELECT date(period) AS d, count(DISTINCT recorder) AS docs, count(*) AS hdr_rows
FROM sales GROUP BY 1 ORDER BY 1

-- [PG] 3.2 DWH посуточно из sales_positions: rows, SUM stoimost/nds c NULLIF NaN
SELECT date(period) AS d, count(*) AS rws,
       SUM(NULLIF(stoimost,'NaN'::numeric)) AS stoimost,
       SUM(NULLIF(nds,'NaN'::numeric)) AS nds,
       count(*) FILTER (WHERE stoimost = 'NaN'::numeric) AS stoimost_nan,
       count(*) FILTER (WHERE nds = 'NaN'::numeric) AS nds_nan
FROM sales_positions GROUP BY 1 ORDER BY 1

-- [PG] 3.1 DWH посуточно из sales: distinct recorder (docs)
SELECT date(period) AS d, count(DISTINCT recorder) AS docs, count(*) AS hdr_rows
FROM sales GROUP BY 1 ORDER BY 1

-- [PG] 3.2 DWH посуточно из sales_positions (JOIN sales по sales_id): rows, SUM stoimost/nds c NULLIF NaN + счёт NaN
SELECT date(s.period) AS d, count(*) AS rws,
       SUM(NULLIF(p.stoimost,'NaN'::numeric)) AS stoimost,
       SUM(NULLIF(p.nds,'NaN'::numeric)) AS nds,
       count(*) FILTER (WHERE p.stoimost = 'NaN'::numeric) AS stoimost_nan,
       count(*) FILTER (WHERE p.nds = 'NaN'::numeric) AS nds_nan
FROM sales_positions p JOIN sales s ON s.id = p.sales_id
GROUP BY 1 ORDER BY 1

-- [PG] 3.3 DWH посуточно по recorder_type: rows, docs, суммы
SELECT date(s.period) AS d, p.recorder_type,
       count(DISTINCT p.recorder) AS docs, count(*) AS rws,
       SUM(NULLIF(p.stoimost,'NaN'::numeric)) AS stoimost,
       SUM(NULLIF(p.nds,'NaN'::numeric)) AS nds
FROM sales_positions p JOIN sales s ON s.id = p.sales_id
GROUP BY 1,2 ORDER BY 1,2

-- [MSSQL] 4.1 MSSQL по-документно: recorder(bin), type, день, rows, SUM stoimost/nds — для декомпозиции дельты
SELECT _RecorderRRef, CAST(_RecorderTRef AS int) AS rtype,
       CAST(DATEADD(year,-2000,_Period) AS date) AS d,
       COUNT(*) AS rws, SUM(_Fld17855) AS stoimost, SUM(_Fld17857) AS nds
FROM [UPP_JAN].[dbo].[_AccumRg17844]
WHERE _Period >= '4026-06-15' AND _Period < '4026-07-22'
GROUP BY _RecorderRRef, CAST(_RecorderTRef AS int), CAST(DATEADD(year,-2000,_Period) AS date)

-- [PG] 4.2 DWH по-документно: recorder, type, день, rows, SUM stoimost/nds (NaN->NULL)
SELECT p.recorder::text, p.recorder_type, date(s.period) AS d,
       count(*) AS rws,
       SUM(NULLIF(p.stoimost,'NaN'::numeric)) AS stoimost,
       SUM(NULLIF(p.nds,'NaN'::numeric)) AS nds
FROM sales_positions p JOIN sales s ON s.id = p.sales_id
GROUP BY 1,2,3

-- [MSSQL] V4a Перепроверка итогов MSSQL одним запросом (без группировок)
SELECT COUNT(*) AS rws, COUNT(DISTINCT _RecorderRRef) AS docs,
       SUM(_Fld17855) AS stoimost, SUM(_Fld17857) AS nds
FROM [UPP_JAN].[dbo].[_AccumRg17844]
WHERE _Period >= '4026-06-15' AND _Period < '4026-07-22'

-- [PG] V4b Перепроверка итогов DWH одним запросом
SELECT count(*) AS rws, count(DISTINCT p.recorder) AS docs,
       SUM(NULLIF(p.stoimost,'NaN'::numeric)) AS stoimost,
       SUM(NULLIF(p.nds,'NaN'::numeric)) AS nds
FROM sales_positions p JOIN sales s ON s.id=p.sales_id
WHERE s.period >= '2026-06-15' AND s.period < '2026-07-22'

-- [MSSQL] V2a Призрак в DWH: строки регистра по этому _RecorderRRef (ожидаем 0)
SELECT COUNT(*) FROM [UPP_JAN].[dbo].[_AccumRg17844] WHERE _RecorderRRef = 0xBC872C4D545A077511F176BDB9127F17

-- [MSSQL] V2b Призрак: шапка _Document476 (существует ли документ, проведён ли)
SELECT _IDRRef, _Posted, _Marked, _Number, DATEADD(year,-2000,_Date_Time) AS dt
