-- [MSSQL] V3a Stale-документ 06-19: строки регистра в MSSQL сейчас
SELECT _LineNo, _Fld17855 AS stoimost, _Fld17857 AS nds, DATEADD(year,-2000,_Period) AS period
FROM [UPP_JAN].[dbo].[_AccumRg17844] WHERE _RecorderRRef = 0x81C004D4C4D2BB6F11F16BC0277169C0 ORDER BY _LineNo

-- [PG] V3b Тот же документ в DWH: строки sales_positions
SELECT p.line_no, p.stoimost, p.nds, s.period, p.retail_updated_at, p.etl_updated_at
FROM sales_positions p JOIN sales s ON s.id=p.sales_id
WHERE p.recorder = '277169c0-6bc0-11f1-81c0-04d4c4d2bb6f' ORDER BY p.line_no

-- [PG] V3c Пример stale 06-30 (fa0a89b4...): строки DWH и когда обновлялись
SELECT p.line_no, p.stoimost, p.nds, s.period, s.doc_number, s.is_posted, p.etl_updated_at, p.retail_updated_at
FROM sales_positions p JOIN sales s ON s.id=p.sales_id
WHERE p.recorder = 'fa0a89b4-7b7a-11f1-81c3-04d4c4d2bb6f'

-- [MSSQL] V3d Тот же документ в MSSQL-регистре
SELECT _LineNo, _Fld17855, _Fld17857, DATEADD(year,-2000,_Period) AS period
FROM [UPP_JAN].[dbo].[_AccumRg17844] WHERE _RecorderRRef = 0x81C304D4C4D2BB6F11F17B7AFA0A89B4

