-- [PG] 6.2 Семь childless-документов (шапка есть, позиций нет) — их recorder
SELECT s.recorder::text FROM sales s
WHERE NOT EXISTS (SELECT 1 FROM sales_positions p WHERE p.sales_id = s.id)

-- [PG] 1.1 Конфиг движка: where_clause main-источника (standalone AccumRg) register_sources — ожидаем NULL (фильтр только _Period)
SELECT rs.id, rs.register_id, rs.source_code, rs.source_type, rs.mssql_schema, rs.mssql_table,
           rs.where_clause, rs.period_column
    FROM etl_meta.register_sources rs
    WHERE rs.mssql_table LIKE '%AccumRg17844%' OR rs.register_id IN (
       SELECT id FROM etl_meta.registers WHERE code ILIKE '%sales%')
    ORDER BY rs.register_id, rs.source_type

-- [PG] 1.1 Конфиг движка: все источники sales-регистра (id=256): where_clause ожидаем NULL, period_column
SELECT id, register_id, source_code, source_type, mssql_schema, mssql_table, where_clause, period_column
    FROM etl_meta.register_sources ORDER BY register_id, id

-- [PG] 1.2 Регистры: какой register_id у sales
SELECT id, code, pipeline_type FROM etl_meta.registers ORDER BY id

