-- [PG] R8 Childless-доки (7 шт из секции целостности): их recorder
SELECT s.recorder::text FROM sales s WHERE NOT EXISTS (SELECT 1 FROM sales_positions p WHERE p.sales_id = s.id)

-- [PG] R9 Свежий счёт NaN в stoimost/nds позиций (влияние NULLIF на сверку)
SELECT count(*) FILTER (WHERE stoimost = 'NaN'::numeric), count(*) FILTER (WHERE nds = 'NaN'::numeric),
           count(*) FILTER (WHERE stoimost IS NULL), count(*) FILTER (WHERE nds IS NULL) FROM sales_positions
